1	import { copyFile, mkdir, mkdtemp, rm, writeFile } from 'node:fs/promises';
2	import { tmpdir } from 'node:os';
3	import { join, resolve } from 'node:path';
4	import { fileURLToPath } from 'node:url';
5	import { bundle } from '@remotion/bundler';
6	import { ensureBrowser, openBrowser, renderMedia, renderStill, selectComposition } from '@remotion/renderer';
7	import type { LineTiming, RenderArtifact, Scene, Storyboard } from '@dailies/core';
8	import { COMPOSITION_ID, NARRATION_FILE, type ReelProps } from './remotion/config';
9	import { toSrt } from './srt';
10	import { buildTimeline } from './timeline';
11	
12	const ENTRY_POINT = fileURLToPath(new URL('./remotion/index.ts', import.meta.url));
13	
14	type Browser = Awaited<ReturnType<typeof openBrowser>>;
15	type Composition = Awaited<ReturnType<typeof selectComposition>>;
16	interface Stage { serveUrl: string; composition: Composition; browser: Browser }
17	
18	const middle = (slot: { startFrame: number; durationInFrames: number }) => slot.startFrame + Math.floor(slot.durationInFrames / 2);
19	
20	const SCENE_TYPES = new Set<string>(['title', 'prompt', 'terminal', 'diff', 'stats', 'flag', 'end'] satisfies Scene['type'][]);
21	
22	/**
23	 * File name of the still for scene `index`. Stills are numbered because scene ids come from a model and need not
24	 * be unique; the type is only used when it is one of ours, so nothing read from a storyboard can steer the path.
25	 */
26	export function stillName(index: number, type: string): string {
27	  return `${String(index + 1).padStart(2, '0')}-${SCENE_TYPES.has(type) ? type : 'scene'}.png`;
28	}
