30	/** Bundles the composition with `publicDir`, opens one browser for every render in `fn`, and cleans both up. */
31	async function withComposition<T>(inputProps: ReelProps, publicDir: string | null, fn: (stage: Stage) => Promise<T>): Promise<T> {
32	  const work = await mkdtemp(join(tmpdir(), 'dailies-reel-'));
33	  let browser: Browser | undefined;
34	  try {
35	    const emptyPublic = join(work, 'public');
36	    await mkdir(emptyPublic);
37	    const serveUrl = await bundle({ entryPoint: ENTRY_POINT, publicDir: publicDir ?? emptyPublic, outDir: join(work, 'bundle') });
38	    await ensureBrowser();
39	    browser = await openBrowser('chrome');
40	    const composition = await selectComposition({ serveUrl, id: COMPOSITION_ID, inputProps, puppeteerInstance: browser });
41	    return await fn({ serveUrl, composition, browser });
42	  } finally {
43	    await browser?.close({ silent: true });
44	    await rm(work, { recursive: true, force: true });
45	  }
46	}
