import { describe, it, expect, afterAll } from 'vitest';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createMockClient } from '@dailies/agent';
import { DEFAULT_BUDGET, type Storyboard } from '@dailies/core';
import type { RunRecord, StageContext, StageName } from '../../src/index';
import { buildReviewStage, durationFinding, reviewStage } from '../../src/stages/review';

const execFileAsync = promisify(execFile);

const dirs: string[] = [];
const scratch = (): string => {
  const d = mkdtempSync(join(tmpdir(), 'dailies-review-test-'));
  dirs.push(d);
  return d;
};
afterAll(() => {
  for (const d of dirs) rmSync(d, { recursive: true, force: true });
});

async function makeClip(path: string, args: string[]): Promise<void> {
  await execFileAsync('ffmpeg', ['-y', ...args, path]);
}

/** 1.5s red, 2s black, 1s blue: a black segment that starts after the first second. */
async function clipWithBlackSegment(path: string): Promise<void> {
  await makeClip(path, [
    '-f', 'lavfi', '-i', 'color=c=red:s=64x64:d=1.5:r=10',
    '-f', 'lavfi', '-i', 'color=c=black:s=64x64:d=2:r=10',
    '-f', 'lavfi', '-i', 'color=c=blue:s=64x64:d=1:r=10',
    '-filter_complex', '[0:v][1:v][2:v]concat=n=3:v=1:a=0[v]',
    '-map', '[v]', '-pix_fmt', 'yuv420p',
  ]);
}

/** Plain clip with no black frames anywhere. */
async function cleanClip(path: string): Promise<void> {
  await makeClip(path, ['-f', 'lavfi', '-i', 'color=c=red:s=64x64:d=2:r=10', '-pix_fmt', 'yuv420p']);
}

function minimalStoryboard(): Storyboard {
  return {
    runId: 'run1',
    repo: 'acme/repo',
    targetSec: 75,
    facts: {},
    scenes: [
      { id: 'sc_title', type: 'title', lines: [], repo: 'acme/repo', windowLabel: 'today', sessionCount: 1, commitCount: 1 },
      { id: 'sc_end', type: 'end', lines: [], repo: 'acme/repo', verified: 1, flagged: 0 },
    ],
  };
}

function fakeRun(): RunRecord {
  return {
    id: 'r1',
    repoUrl: 'https://example.com/repo.git',
    since: '2026-01-01',
    until: '2026-01-02',
    status: 'running',
    reason: null,
    costUsd: 0,
    loops: 0,
    budget: DEFAULT_BUDGET,
    createdAt: '2026-01-01',
  };
}

function makeCtx(artifacts: Partial<Record<StageName, unknown>>): StageContext {
  return {
    run: fakeRun(),
    dataDir: scratch(),
    runDir: scratch(),
    read: <T>(name: StageName) => artifacts[name] as T,
    log: () => {},
    feedback: null,
  };
}

describe('durationFinding', () => {
  it('reports high severity when the duration exceeds 125% of the target', () => {
    const finding = durationFinding(76, 60); // 60 * 1.25 = 75, 76 is over it
    expect(finding).toMatchObject({ severity: 'high' });
  });

  it('reports nothing exactly at 125% of the target', () => {
    expect(durationFinding(75, 60)).toBeNull(); // 60 * 1.25 = 75 exactly: not "over"
  });

  it('reports high severity when the duration is under the 20s floor', () => {
    const finding = durationFinding(19.9, 75);
    expect(finding).toMatchObject({ severity: 'high' });
  });

  it('reports nothing exactly at the 20s floor', () => {
    expect(durationFinding(20, 75)).toBeNull();
  });
});

describe('buildReviewStage', () => {
  it('loops back to script with a reason naming the scene when the vision check returns a high finding', async () => {
    const stillPath = join(scratch(), 'still.png');
    writeFileSync(stillPath, Buffer.from('fake-png-bytes'));
    const videoPath = join(scratch(), 'clean.mp4');
    await cleanClip(videoPath);

    const client = createMockClient((req) => {
      expect(req.role).toBe('vision');
      return {
        role: 'assistant',
        content: JSON.stringify({
          findings: [{ sceneId: 'sc_terminal', issue: 'narration text overflows the frame', severity: 'high', fix: 'shorten the line' }],
        }),
      };
    });
    const stage = buildReviewStage({ client, renderStills: async () => [{ sceneId: 'sc_terminal', path: stillPath }] });

    const ctx = makeCtx({
      render: { videoPath, srtPath: 'x.srt', posterPath: 'x.png', durationSec: 75 },
      ground: { storyboard: minimalStoryboard() },
      voice: { audioPath: null, timings: [] },
    });

    const result = await stage.run(ctx);

    expect(result.artifact.pass).toBe(false);
    expect(result.loopBackTo).toBe('script');
    expect(result.reason).toContain('sc_terminal');
    expect(result.artifact.findings.some((f) => f.severity === 'high')).toBe(true);
  }, 20000);

  it('passes when the vision check returns no findings and the deterministic checks are clean', async () => {
    const stillPath = join(scratch(), 'still.png');
    writeFileSync(stillPath, Buffer.from('fake-png-bytes'));
    const videoPath = join(scratch(), 'clean.mp4');
    await cleanClip(videoPath);

    const client = createMockClient(() => ({ role: 'assistant', content: JSON.stringify({ findings: [] }) }));
    const stage = buildReviewStage({ client, renderStills: async () => [{ sceneId: 'sc_terminal', path: stillPath }] });

    const ctx = makeCtx({
      render: { videoPath, srtPath: 'x.srt', posterPath: 'x.png', durationSec: 75 },
      ground: { storyboard: minimalStoryboard() },
      voice: { audioPath: null, timings: [] },
    });

    const result = await stage.run(ctx);

    expect(result.artifact).toEqual({ pass: true, findings: [] });
    expect(result.loopBackTo).toBeUndefined();
  }, 20000);

  it('reports a black segment that starts after the first second as a high finding', async () => {
    const videoPath = join(scratch(), 'black.mp4');
    await clipWithBlackSegment(videoPath);

    const client = createMockClient(() => {
      throw new Error('should not call the model when there are no stills');
    });
    const stage = buildReviewStage({ client, renderStills: async () => [] });

    const ctx = makeCtx({
      render: { videoPath, srtPath: 'x.srt', posterPath: 'x.png', durationSec: 75 },
      ground: { storyboard: minimalStoryboard() },
      voice: { audioPath: null, timings: [] },
    });

    const result = await stage.run(ctx);

    expect(result.artifact.pass).toBe(false);
    expect(result.loopBackTo).toBe('script');
    expect(result.artifact.findings.some((f) => f.severity === 'high' && f.issue.includes('black'))).toBe(true);
  }, 20000);

  it('does not report a black segment that ends within the first second', async () => {
    const videoPath = join(scratch(), 'brief-open.mp4');
    await makeClip(videoPath, [
      '-f', 'lavfi', '-i', 'color=c=black:s=64x64:d=0.6:r=10',
      '-f', 'lavfi', '-i', 'color=c=red:s=64x64:d=2:r=10',
      '-filter_complex', '[0:v][1:v]concat=n=2:v=1:a=0[v]',
      '-map', '[v]', '-pix_fmt', 'yuv420p',
    ]);

    const client = createMockClient(() => ({ role: 'assistant', content: JSON.stringify({ findings: [] }) }));
    const stage = buildReviewStage({ client, renderStills: async () => [] });

    const ctx = makeCtx({
      render: { videoPath, srtPath: 'x.srt', posterPath: 'x.png', durationSec: 75 },
      ground: { storyboard: minimalStoryboard() },
      voice: { audioPath: null, timings: [] },
    });

    const result = await stage.run(ctx);

    expect(result.artifact.pass).toBe(true);
  }, 20000);
});

describe('reviewStage', () => {
  it('builds a stage named review that wires the real renderStills implementation', () => {
    const stage = reviewStage({ client: createMockClient(() => ({ role: 'assistant', content: '{}' })) });
    expect(stage.name).toBe('review');
    expect(stage.maxAttempts).toBeGreaterThan(0);
  });
});

import type { ContentPart } from '@dailies/agent';

const RUBRIC = `You are reviewing stills captured from a rendered video reel, one per scene, each labelled with its scene id.
For each still, check for:
- text cut off or overflowing its frame
- an empty or near-empty frame
- unreadable contrast between text and its background
- content that does not match the scene type implied by its label

Reply with JSON only, matching this schema: { "findings": [{ "sceneId": string | null, "issue": string, "severity": "low" | "high", "fix": string }] }.
Report a finding only for a still with an actual problem. Reply { "findings": [] } when every still is correct.`;

export function reviewerPrompt(stills: { sceneId: string; dataUrl: string }[]): { system: string; user: ContentPart[] } {
  const user: ContentPart[] = stills.flatMap((s) => [
    { type: 'text', text: `Still for scene ${s.sceneId}:` },
    { type: 'image_url', image_url: { url: s.dataUrl } },
  ]);
  return { system: RUBRIC, user };
}

import { execFile } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { promisify } from 'node:util';
import { z } from 'zod';
import { completeJson, type ModelClient } from '@dailies/agent';
import { detectSilences } from '@dailies/voice';
import { renderStills as renderStillsReal } from '@dailies/reel';
import { Finding, type LineTiming, type RenderArtifact, type Storyboard } from '@dailies/core';
import type { Stage, StageContext, StageResult } from '../types';
import { reviewerPrompt } from '../prompts/reviewer';

const execFileAsync = promisify(execFile);
const STILL_BATCH_SIZE = 4;
const DURATION_FLOOR_SEC = 20;

// Task 8 (not merged into this worktree) owns `GroundArtifact`/`VoiceArtifact`; these mirror the
// shapes documented in the plan's Task 8 Interfaces for the two fields this stage actually reads.
interface ReviewGroundInput {
  storyboard: Storyboard;
}
interface ReviewVoiceInput {
  audioPath: string | null;
  timings: LineTiming[];
}

export function durationFinding(actualSec: number, targetSec: number): Finding | null {
  if (actualSec > targetSec * 1.25) {
    return {
      sceneId: null,
      issue: `reel runs ${actualSec.toFixed(1)}s, more than 25% over the ${targetSec}s target`,
      severity: 'high',
      fix: 'shorten narration lines or drop a scene',
    };
  }
  if (actualSec < DURATION_FLOOR_SEC) {
    return {
      sceneId: null,
      issue: `reel runs ${actualSec.toFixed(1)}s, under the ${DURATION_FLOOR_SEC}s floor`,
      severity: 'high',
      fix: 'add scenes or narration',
    };
  }
  return null;
}

async function runFfmpegStderr(args: string[]): Promise<string> {
  try {
    const { stderr } = await execFileAsync('ffmpeg', args, { maxBuffer: 16 * 1024 * 1024 });
    return stderr;
  } catch (err) {
    return (err as { stderr?: string }).stderr ?? '';
  }
}

async function blackFindings(videoPath: string): Promise<Finding[]> {
  const stderr = await runFfmpegStderr(['-i', videoPath, '-vf', 'blackdetect=d=0.5', '-an', '-f', 'null', '-']);
  const findings: Finding[] = [];
  for (const m of stderr.matchAll(/black_start:([\d.]+) black_end:([\d.]+) black_duration:([\d.]+)/g)) {
    const start = Number(m[1]);
    if (start > 1) {
      findings.push({
        sceneId: null,
        issue: `black frames from ${m[1]}s to ${m[2]}s (${m[3]}s)`,
        severity: 'high',
        fix: 'investigate the render for the scene at that timestamp',
      });
    }
  }
  return findings;
}

async function silenceFindings(audioPath: string | null): Promise<Finding[]> {
  if (audioPath === null) return [];
  const gaps = await detectSilences(audioPath, { minSec: 1.8 });
  return gaps.map((g) => ({
    sceneId: null,
    issue: `silent gap from ${g.start.toFixed(1)}s to ${g.end.toFixed(1)}s in the narration`,
    severity: 'low' as const,
    fix: 'tighten the pause or re-time the line',
  }));
}

function toDataUrl(path: string): string {
  return `data:image/png;base64,${readFileSync(path).toString('base64')}`;
}

const VisionReply = z.object({ findings: z.array(Finding) });

async function visionFindings(client: ModelClient, stills: { sceneId: string; path: string }[]): Promise<Finding[]> {
  const findings: Finding[] = [];
  for (let i = 0; i < stills.length; i += STILL_BATCH_SIZE) {
    const batch = stills.slice(i, i + STILL_BATCH_SIZE);
    const { system, user } = reviewerPrompt(batch.map((s) => ({ sceneId: s.sceneId, dataUrl: toDataUrl(s.path) })));
    const reply = await completeJson({ client, role: 'vision', name: 'reviewer', system, user, output: VisionReply });
    findings.push(...reply.findings);
  }
  return findings;
}

export interface ReviewStageDeps {
  client: ModelClient;
  renderStills: typeof renderStillsReal;
}

/** Same behaviour as `reviewStage`, with `renderStills` injectable so unit tests never drive a real browser. */
export function buildReviewStage(deps: ReviewStageDeps): Stage<{ pass: boolean; findings: Finding[] }> {
  return {
    name: 'review',
    maxAttempts: 2,
    async run(ctx: StageContext): Promise<StageResult<{ pass: boolean; findings: Finding[] }>> {
      const render = ctx.read<RenderArtifact>('render');
      const ground = ctx.read<ReviewGroundInput>('ground');
      const voice = ctx.read<ReviewVoiceInput>('voice');

      const findings: Finding[] = [];
      const duration = durationFinding(render.durationSec, ground.storyboard.targetSec);
      if (duration) findings.push(duration);
      findings.push(...(await blackFindings(render.videoPath)));
      findings.push(...(await silenceFindings(voice.audioPath)));

      const stills = await deps.renderStills({
        storyboard: ground.storyboard,
        timings: voice.timings,
        outDir: join(ctx.runDir, 'review-stills'),
      });
      findings.push(...(await visionFindings(deps.client, stills)));

      const pass = !findings.some((f) => f.severity === 'high');
      if (!pass) {
        const reason = findings.map((f) => `${f.sceneId ?? 'reel'}: ${f.issue}`).join('; ');
        return { artifact: { pass, findings }, loopBackTo: 'script', reason };
      }
      return { artifact: { pass, findings } };
    },
  };
}

export function reviewStage(deps: { client: ModelClient }): Stage<{ pass: boolean; findings: Finding[] }> {
  return buildReviewStage({ client: deps.client, renderStills: renderStillsReal });
}

